"use client";

import { useEffect, useMemo, useState } from "react";
import DashboardScaffold from "@/components/DashboardScaffold";
import { apiFetch } from "@/app/dashboard/_lib/api";
import { useRequireAuth } from "@/app/dashboard/_lib/useRequireAuth";
import { useUiPreferences } from "@/lib/use-ui-preferences";
import {
  MODULE_WINDOW_CATALOG,
  WINDOW_ROLE_PRESETS,
  type WindowRole,
  normalizeRole,
} from "@/lib/window-layout-presets";

type CurrentUserPayload = {
  role?: string | null;
};

const ROLE_OPTIONS: WindowRole[] = ["USER", "GERENTE", "ADMIN"];

export default function LayoutsClientPage() {
  const hasToken = useRequireAuth();
  const { getModulePrefs, updateModule, applyRolePreset, resetAll } = useUiPreferences();
  const [role, setRole] = useState<WindowRole>("USER");
  const [activeModule, setActiveModule] = useState<string>("inbox");
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    if (hasToken !== true) return;
    apiFetch<CurrentUserPayload>("/profile/current-user")
      .then((payload) => setRole(normalizeRole(payload?.role)))
      .catch(() => setRole("USER"));
  }, [hasToken]);

  const moduleKeys = useMemo(() => Object.keys(MODULE_WINDOW_CATALOG), []);
  const availablePanels = MODULE_WINDOW_CATALOG[activeModule] || [];
  const currentPrefs = getModulePrefs(activeModule, role);
  const visiblePanels = currentPrefs.visiblePanels || [];
  const layoutMode = currentPrefs.layoutMode || "horizontal";
  const primaryPanelPosition = currentPrefs.primaryPanelPosition || "left";
  const splitPercent = Math.min(
    80,
    Math.max(20, currentPrefs.splitPercent ?? currentPrefs.sidebarPercent ?? 40),
  );

  function togglePanel(panelId: string) {
    const next = visiblePanels.includes(panelId)
      ? visiblePanels.filter((id) => id !== panelId)
      : [...visiblePanels, panelId];
    if (next.length === 0) return;
    updateModule(activeModule, { visiblePanels: next });
  }

  if (hasToken === null) {
    return (
      <main className="app-shell">
        <div className="app-container">
          <div className="panel p-4 text-sm text-muted">Carregando...</div>
        </div>
      </main>
    );
  }

  if (!hasToken) return null;

  return (
    <DashboardScaffold
      title="Layout ERP"
      description="Gerencie janelas por módulo e aplique presets por função."
      actions={
        <div className="flex gap-2">
          <button
            type="button"
            className="btn btn-secondary btn-sm"
            onClick={() => {
              applyRolePreset(activeModule, role);
              setMessage(`Preset ${role} aplicado em ${activeModule}.`);
            }}
          >
            Aplicar preset da função
          </button>
          <button
            type="button"
            className="btn btn-danger btn-sm"
            onClick={() => {
              resetAll();
              setMessage("Layout resetado para o padrão.");
            }}
          >
            Reset geral
          </button>
        </div>
      }
    >
      {message ? <div className="msg-info"><div className="text-sm">{message}</div></div> : null}

      <section className="panel p-4 grid gap-4">
        <div className="grid gap-2 md:grid-cols-3">
          <label className="grid gap-1">
            <span className="text-xs uppercase tracking-[0.08em] text-muted font-semibold">Módulo</span>
            <select
              className="field"
              value={activeModule}
              onChange={(event) => setActiveModule(event.target.value)}
            >
              {moduleKeys.map((moduleKey) => (
                <option key={moduleKey} value={moduleKey}>
                  {moduleKey}
                </option>
              ))}
            </select>
          </label>

          <label className="grid gap-1">
            <span className="text-xs uppercase tracking-[0.08em] text-muted font-semibold">Função</span>
            <select
              className="field"
              value={role}
              onChange={(event) => setRole(normalizeRole(event.target.value))}
            >
              {ROLE_OPTIONS.map((roleOption) => (
                <option key={roleOption} value={roleOption}>
                  {roleOption}
                </option>
              ))}
            </select>
          </label>

          <div className="grid gap-1">
            <span className="text-xs uppercase tracking-[0.08em] text-muted font-semibold">Preset disponível</span>
            <div className="rounded-[10px] border border-[var(--line)] px-3 py-2 text-sm bg-[var(--surface-soft)]">
              {(WINDOW_ROLE_PRESETS[activeModule]?.[role]?.visiblePanels || []).join(", ") || "-"}
            </div>
          </div>
        </div>

        <div className="grid gap-2">
          <p className="text-xs uppercase tracking-[0.08em] text-muted font-semibold m-0">
            Janelas disponíveis no módulo
          </p>
          <div className="grid gap-2 md:grid-cols-2">
            {availablePanels.map((panel) => (
              <label
                key={panel.id}
                className="flex items-start gap-2 rounded-[10px] border border-[var(--line)] px-3 py-2"
              >
                <input
                  type="checkbox"
                  checked={visiblePanels.includes(panel.id)}
                  onChange={() => togglePanel(panel.id)}
                />
                <span className="grid gap-0.5">
                  <strong className="text-sm">{panel.label}</strong>
                  <small className="text-xs text-muted">{panel.description}</small>
                </span>
              </label>
            ))}
          </div>
        </div>

        {(activeModule === "inbox" || activeModule === "recovery") && (
          <div className="grid gap-2">
            <p className="text-xs uppercase tracking-[0.08em] text-muted font-semibold m-0">
              Docking e redimensionamento
            </p>
            <div className="grid gap-2 md:grid-cols-3">
              <label className="grid gap-1">
                <span className="text-xs text-muted">Modo</span>
                <select
                  className="field"
                  value={layoutMode}
                  onChange={(event) =>
                    updateModule(activeModule, {
                      layoutMode: event.target.value === "vertical" ? "vertical" : "horizontal",
                    })
                  }
                >
                  <option value="horizontal">Lado a lado</option>
                  <option value="vertical">Cima e baixo</option>
                </select>
              </label>

              <label className="grid gap-1">
                <span className="text-xs text-muted">Posição da janela principal</span>
                <select
                  className="field"
                  value={primaryPanelPosition}
                  onChange={(event) =>
                    updateModule(activeModule, {
                      primaryPanelPosition: ["left", "right", "top", "bottom"].includes(
                        event.target.value,
                      )
                        ? (event.target.value as "left" | "right" | "top" | "bottom")
                        : "left",
                    })
                  }
                >
                  <option value="left">Esquerda</option>
                  <option value="right">Direita</option>
                  <option value="top">Cima</option>
                  <option value="bottom">Baixo</option>
                </select>
              </label>

              <label className="grid gap-1">
                <span className="text-xs text-muted">Split ({splitPercent}%)</span>
                <input
                  type="range"
                  min={20}
                  max={80}
                  value={splitPercent}
                  onChange={(event) => {
                    const value = Number(event.target.value || 40);
                    updateModule(activeModule, {
                      splitPercent: value,
                      sidebarPercent: value,
                    });
                  }}
                />
              </label>
            </div>
          </div>
        )}
      </section>
    </DashboardScaffold>
  );
}
